package com.renthub.bookingservice; import com.renthub.auth.AuthService; import com.renthub.booking.*; import com.renthub.service.*; import com.renthub.user.User; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*; @RestController @RequestMapping("/api/booking-services") @CrossOrigin(origins="http://localhost:5173") public class BookingServiceAddonController{private final BookingServiceAddonRepository repo;private final BookingRepository bookings;private final ExtraServiceRepository services;private final AuthService auth;public BookingServiceAddonController(BookingServiceAddonRepository r,BookingRepository b,ExtraServiceRepository s,AuthService a){repo=r;bookings=b;services=s;auth=a;} @GetMapping("/{bookingId}") public List<BookingServiceAddon> list(@RequestHeader(value="Authorization",required=false)String h,@PathVariable Long bookingId){User u=auth.require(h);Booking b=bookings.findById(bookingId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Booking not found"));if(!b.getUserId().equals(u.getId())&&!"ADMIN".equals(u.getRole()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Not your booking");return repo.findByBookingId(bookingId);} @PostMapping("/{bookingId}/{serviceId}") public BookingServiceAddon add(@RequestHeader(value="Authorization",required=false)String h,@PathVariable Long bookingId,@PathVariable Long serviceId){User u=auth.require(h);Booking b=bookings.findById(bookingId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Booking not found"));if(!b.getUserId().equals(u.getId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Not your booking");if(repo.existsByBookingIdAndServiceId(bookingId,serviceId))throw new ResponseStatusException(HttpStatus.CONFLICT,"Service already added");ExtraService s=services.findById(serviceId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Service not found"));BookingServiceAddon x=new BookingServiceAddon();x.setBookingId(bookingId);x.setServiceId(serviceId);x.setPrice(s.getPrice());return repo.save(x);}}
